def prime_factorization(n):
    """Returns a dictionary of prime factors and their exponents for n."""
    factors = {}
    d = 2
    temp = n
    while d * d <= temp:
        while temp % d == 0:
            factors[d] = factors.get(d, 0) + 1
            temp //= d
        d += 1
    if temp > 1:
        factors[temp] = factors.get(temp, 0) + 1
    return factors

def calculate_tau_n_12(n):
    """Calculates tau(n^12)."""
    if n == 1:
        return 1

    factors = prime_factorization(n)
    tau = 1
    for exponent in factors.values():
        # If n = p^e, then n^12 = p^(12e). The factor in tau is (12e + 1).
        tau *= (12 * exponent + 1)
    return tau

